# GCL_PUBLIC_RESEARCH grandchallenge/MATH-PROGRAMME e20204b69137add0d791addca222762503cd79e6
# GCL_THREAD: EXT-015-UC114
# GCL_TITLE: Affine reconstruction of the free-scalar collision model
# GCL_OBJECTIVE: Check the exact polynomial controls for the finite reconstruction stages.
# GCL_RESEARCH: What survives the first derived overlap and its higher iterations?
# GCL_EXECUTE: Enumerate ordered pair-relation words and minimal weights using exact small integers.
set -eu
awk '
function require(condition, label) {
    if (!condition) { print "FAIL " label; exit 1 }
}
BEGIN {
    rank[0] = 1
    for (weight = 1; weight <= 8; weight++) {
        for (var = 1; var <= weight + 1; var++) {
            for (j = weight; j <= 8; j++) rank[j] += rank[j - weight]
        }
    }
    for (j = 2; j <= 8; j++) rank[j] += rank[j - 2]
    require(rank[2] == 7 && rank[4] == 40, "vacuum and arity ranks")
    words = 0
    for (k = 1; k <= 8; k++) {
        total = int(3^k)
        im = 0
        for (word = 0; word < total; word++) {
            a = 0; b = 0; c = 0; v = word
            for (i = 0; i < k; i++) {
                x = v % 3; v = int(v/3)
                if (x == 0) a++
                if (x == 1) b++
                if (x == 2) c++
            }
            key = k ":" a ":" b ":" c
            if (!(key in seen)) { seen[key] = 1; im++ }
            words++
        }
        require(im == (k+1)*(k+2)/2, "ordered-to-symmetric image")
        if (k == 2) require(rank[4]-im == 34 && total-im == 3, "weight four partial stage")
    }
    threshold_checks = 0
    for (k = 1; k <= 12; k++) {
        minimum = 1000
        for (a = 0; a <= k; a++) for (b = 0; b <= k-a; b++) {
            c = k-a-b
            value = 2*a+3*b+4*c
            if (value < minimum) minimum = value
            threshold_checks++
        }
        require(minimum == 2*k, "minimal fiber weight")
    }
    print "GCL_FINDING: Exact finite controls passed on " words " ordered words and " threshold_checks " weight assignments. The weight-four ranks are 40 before partial reconstruction, 34 in degree zero and 3 in degree minus one at stage one."
}'

# GCL_PUBLIC_RESEARCH grandchallenge/MATH-PROGRAMME 360666b615176ac7edb0c9956cbfa3c8d8b6095e
# GCL_THREAD: EXT-015-UC117
# GCL_TITLE: Explicit maps for the affine overlap diagram
# GCL_OBJECTIVE: Check the ordinal maps and signed weight-four reconstruction in the free-scalar model.
# GCL_RESEARCH: Do the explicit addition and collapse maps yield the six actual pair products?
# GCL_EXECUTE: Enumerate ordinal map composites and integer coefficients of the exterior boundaries.
set -eu
awk '
function require(ok, reason) {
    if (!ok) { print "FAIL: " reason; exit 1 }
}
function add(w, a, b, coefficient) {
    if (a < b) w[a,b] += coefficient
    if (a > b) w[b,a] -= coefficient
}
BEGIN {
    comparisons = 0
    for (n = 1; n <= 5; n++) for (m = 1; m <= 5; m++) {
        for (word = 0; word < m^n; word++) {
            z = word; valid = 1; previous = -1
            for (i = 0; i < n; i++) {
                tmp[i] = z % m; z = int(z/m)
                if (tmp[i] < previous) valid = 0
                previous = tmp[i]
            }
            if (!valid) continue
            count[n,m]++
            for (i = 0; i < n; i++) maps[n,m,count[n,m],i] = tmp[i]
        }
    }
    for (n = 2; n <= 5; n++) for (m = 1; m <= 5; m++) for (l = 2; l <= 5; l++)
    for (a = 1; a <= count[n,m]; a++) for (b = 1; b <= count[m,l]; b++)
    for (i = 1; i < n; i++) for (k = 1; k < l; k++) {
        low = maps[n,m,a,i-1]; high = maps[n,m,a,i]
        pieces = 0
        for (j = low+1; j <= high; j++)
            if (maps[m,l,b,j-1] < k && k <= maps[m,l,b,j]) pieces++
        whole = (maps[m,l,b,low] < k && k <= maps[m,l,b,high])
        require(pieces == whole, "interval sums compose")
        comparisons++
    }

    column = 0
    for (x = 1; x <= 3; x++) for (y = x+1; y <= 3; y++) {
        split("", w)
        add(w, x+3, y+3, 1)
        add(w, x, y, -1); add(w, x, y+3, -1)
        add(w, x+3, y, -1); add(w, x+3, y+3, -1)
        add(w, x, y, 1)
        column++
        for (i = 1; i <= 6; i++) for (j = i+1; j <= 6; j++) {
            expected = ((i==y && j==x+3)?1:0)-((i==x && j==y+3)?1:0)
            require(w[i,j] == expected, "exterior coface sign")
            if (i <= 3 && j > 3) matrix[3*(i-1)+j-3,column] = w[i,j]
        }
    }
    rank = 0
    for (j = 1; j <= 3; j++) {
        pivot = 0
        for (i = rank+1; i <= 9; i++) if (matrix[i,j] != 0) { pivot=i; break }
        if (!pivot) continue
        rank++
        for (k = j; k <= 3; k++) {
            value = matrix[rank,k]; matrix[rank,k] = matrix[pivot,k]; matrix[pivot,k] = value
        }
        for (i = rank+1; i <= 9; i++) {
            factor=matrix[i,j]; denominator=matrix[rank,j]
            for (k = j; k <= 3; k++) matrix[i,k] = denominator*matrix[i,k]-factor*matrix[rank,k]
        }
    }
    require(rank == 3 && 9-rank == 6, "six symmetric classes")

    transgression_checks = 0
    for (x = 1; x <= 3; x++) for (y = 1; y <= 3; y++) {
        split("", w); split("", want)
        add(w, x+3, y+6, 1); add(w, x+3, y+3, -1)
        add(w, x, y+6, -1); add(w, x, y, 1)
        add(w, x, y+3, 1); add(w, x, y, -1)
        add(want, x+3, y+6, 1); add(want, x+3, y+3, -1)
        add(want, x, y+6, -1); add(want, x, y+3, 1)
        for (i = 1; i <= 9; i++) for (j = i+1; j <= 9; j++) {
            require(w[i,j] == want[i,j], "signed quadratic transgression")
            transgression_checks++
        }
    }
    print "GCL_FINDING: " comparisons " ordinal coefficient checks and " transgression_checks " signed quadratic coefficient checks passed. The mixed sector has dimension 9, alternating image rank 3, symmetric quotient rank 6."
}'
